def count_vowels(s):
	return sum((1 if c in {'a', 'e', 'i', 'o', 'u'} else 0 for c in s))

def last_vowel(s):
	answer = s[0]
	for c in s:
		if c in {'a', 'e', 'i', 'o', 'u'}:
			answer = c
	return answer
n = int(input())
ss = [input() for _ in range(n)]
d = {}
for s in ss:
	(c, l) = (count_vowels(s), last_vowel(s))
	if (c, l) not in d:
		d[c, l] = []
	d[c, l].append(s)
p2 = []
for (c, l) in d:
	ldcl = len(d[c, l])
	while ldcl > 1:
		p2.append((d[c, l][-2], d[c, l][-1]))
		d[c, l].pop()
		d[c, l].pop()
		ldcl -= 2
p1 = []
d2 = {}
for (c, l) in d:
	if len(d[c, l]) > 0:
		if c not in d2:
			d2[c] = []
		d2[c].append(d[c, l][0])
for c in d2:
	ld2c = len(d2[c])
	while ld2c > 1:
		p1.append((d2[c][-2], d2[c][-1]))
		d2[c].pop()
		d2[c].pop()
		ld2c -= 2
pp = []
(lp1, lp2) = (len(p1), len(p2))
while lp1 > 0 and lp2 > 0:
	pp.append(((p1[-1][0], p2[-1][0]), (p1[-1][1], p2[-1][1])))
	p1.pop()
	p2.pop()
	lp1 -= 1
	lp2 -= 1
while lp2 > 1:
	pp.append(((p2[-2][0], p2[-1][0]), (p2[-2][1], p2[-1][1])))
	p2.pop()
	p2.pop()
	lp2 -= 2
print(len(pp))
for ((a, b), (c, d)) in pp:
	print(f'{a} {b}\n{c} {d}')
